package com.nextrade.persistence.entity; import jakarta.persistence.*; import java.math.*; import java.util.*; @Entity @Table(name="wallet",uniqueConstraints=@UniqueConstraint(name="ux_wallet_user_currency",columnNames={"userId","currency"})) public class WalletEntity {@Id private UUID id;@Column(nullable=false)private UUID userId;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,precision=19,scale=4)private BigDecimal available=BigDecimal.ZERO;@Column(nullable=false,precision=19,scale=4)private BigDecimal reserved=BigDecimal.ZERO;@Version private long version;public WalletEntity(){}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public String getCurrency(){return currency;}public void setCurrency(String v){currency=v;}public BigDecimal getAvailable(){return available;}public void setAvailable(BigDecimal v){available=v;}public BigDecimal getReserved(){return reserved;}public void setReserved(BigDecimal v){reserved=v;}public long getVersion(){return version;}}
